import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as s,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"扣子编程 Cookbook","description":"按场景跳着读：工作流、插件、知识库、技能、发布、Coze CLI。每条都链回官方页。不写豆包或 Trae 教程。","frontmatter":{"title":"扣子编程 Cookbook","description":"按场景跳着读：工作流、插件、知识库、技能、发布、Coze CLI。每条都链回官方页。不写豆包或 Trae 教程。","domain":"product","tags":["agent-builder"],"role":"cookbook"},"headers":[],"relativePath":"zh/products/coze/coze-cookbook.md","filePath":"zh/products/coze/coze-cookbook.md","lastUpdated":1787107158000}'),o={name:"zh/products/coze/coze-cookbook.md"};function n(r,t,l,p,d,h){return s(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="扣子编程-cookbook" tabindex="-1">扣子编程 Cookbook <a class="header-anchor" href="#扣子编程-cookbook" aria-label="Permalink to &quot;扣子编程 Cookbook&quot;">​</a></h1><p>已经会创建低代码智能体。这里只给<strong>场景配方</strong>。基础点击回 <a href="./coze.html">教程</a>。</p><h2 id="先搭工作流-再挂到智能体" tabindex="-1">先搭工作流，再挂到智能体 <a class="header-anchor" href="#先搭工作流-再挂到智能体" aria-label="Permalink to &quot;先搭工作流，再挂到智能体&quot;">​</a></h2><p>固定多步任务不要全塞进人设。官方把工作流定义成「可执行指令的集合」，用画布拖节点。</p><p>两种类型（<a href="https://docs.coze.cn/guides_workflow" target="_blank" rel="noreferrer">低代码工作流</a>）：</p><table tabindex="0"><thead><tr><th>类型</th><th>用途</th><th>例子</th></tr></thead><tbody><tr><td>工作流 Workflow</td><td>顺序执行，面向功能 / 数据</td><td>调研报告、海报、绘本</td></tr><tr><td>对话流 Chatflow</td><td>面向对话，边聊边走复杂逻辑</td><td>客服、个人助手</td></tr></tbody></table><p>每个工作流默认有 <strong>开始</strong> 和 <strong>结束</strong> 节点。用引用把上游输出接到下游输入。节点支持 <code>String</code>、<code>Integer</code>、<code>Number</code>、<code>Boolean</code>、<code>Object</code>、<code>File</code>、<code>Array</code>。</p><p>付费节点跑成功就会计费；<strong>整个工作流失败，已经成功的付费节点仍计费</strong>。</p><p>权限：空间成员默认可创建 / 查看 / 复制 / 导入。编辑和发布要所有者先开协作并加你。细节以官方权限表为准。</p><p>自然语言生成全代码工作流走另一条路：<a href="https://docs.coze.cn/guides_ai_powered_workflow_development" target="_blank" rel="noreferrer">开发工作流</a>。</p><h2 id="给智能体外挂-api-插件" tabindex="-1">给智能体外挂 API：插件 <a class="header-anchor" href="#给智能体外挂-api-插件" aria-label="Permalink to &quot;给智能体外挂 API：插件&quot;">​</a></h2><p>插件是工具集，里面每个工具是一个 API。同一插件内的工具必须同域名（<a href="https://docs.coze.cn/guides_plugin" target="_blank" rel="noreferrer">插件介绍</a>）。</p><table tabindex="0"><thead><tr><th>分类</th><th>谁维护</th><th>计费</th></tr></thead><tbody><tr><td>资源库插件</td><td>你自己，仅当前账号</td><td>看你接入的 API</td></tr><tr><td>官方插件</td><td>扣子编程</td><td>按调用量，可用积分抵扣</td></tr><tr><td>三方插件</td><td>其他开发者</td><td>付费项从<strong>现金余额</strong>扣，不能用积分</td></tr></tbody></table><p>自定义插件可以：基于 API、用 IDE、导入 JSON/YAML、用代码注册。</p><p>硬限制（官方原文）：</p><ul><li>每空间最多 1000 个插件；每账号最多 30 个 IDE 插件。</li><li>每插件最多 100 个工具。</li><li>自定义插件 QPS 最大 50。</li><li>依赖包总大小上限 250 MB。</li><li><strong>加了三方付费插件的低代码智能体或应用，不能发到飞书多维表格、掘金、豆包及部分公共渠道。</strong></li></ul><p>智能体里加了插件之后，人设必须 <code>{</code> 引用，否则可能不调用。工作流里则把插件当成节点。</p><h2 id="用知识库补垂直事实" tabindex="-1">用知识库补垂直事实 <a class="header-anchor" href="#用知识库补垂直事实" aria-label="Permalink to &quot;用知识库补垂直事实&quot;">​</a></h2><p>模型会幻觉。静态、全员共享、由开发者维护的内容放知识库，不要放记忆（<a href="https://docs.coze.cn/guides_knowledge" target="_blank" rel="noreferrer">知识库概述</a>）。</p><table tabindex="0"><thead><tr><th></th><th>知识</th><th>记忆</th></tr></thead><tbody><tr><td>谁改</td><td>开发者</td><td>终端用户在对话里产生</td></tr><tr><td>谁看见</td><td>空间内可共享，用户不能改</td><td>跟用户走，不能跨智能体</td></tr><tr><td>例子（租房）</td><td>房源、小区、政策 PDF</td><td>用户偏好、关注列表</td></tr></tbody></table><p>两条产品线：</p><ul><li><strong>扣子知识库</strong>：文本 / 表格 / 图片。有免费额度，适合先试。</li><li><strong>火山知识库</strong>：企业级，上传即开始在火山侧计费，<strong>不能用扣子积分抵扣</strong>。删文档不会停计算资源费，不用了要解绑并在火山控制台删库。</li></ul><p>流程：创建或关联 → 绑到智能体或工作流 → 配检索 / 召回 → 再调试。</p><h2 id="把-sop-收成技能-而不是再写长-prompt" tabindex="-1">把 SOP 收成技能，而不是再写长 Prompt <a class="header-anchor" href="#把-sop-收成技能-而不是再写长-prompt" aria-label="Permalink to &quot;把 SOP 收成技能，而不是再写长 Prompt&quot;">​</a></h2><p>技能是带 <code>SKILL.md</code> 的文件夹，按需加载，不是全程生效的人设（<a href="https://docs.coze.cn/guides_skill_overview" target="_blank" rel="noreferrer">技能概述</a>）。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-skill/</span></span>
<span class="line"><span>├── SKILL.md          # 必选：名称、用途、元数据</span></span>
<span class="line"><span>├── scripts/          # 可选：可执行代码</span></span>
<span class="line"><span>├── references/       # 可选：参考文档</span></span>
<span class="line"><span>└── assets/           # 可选：模板和静态资源</span></span></code></pre></div><p>对比一句话：</p><ul><li><strong>提示词</strong>：全局人设，每轮都在。</li><li><strong>技能</strong>：某类任务的 SOP，相关时才加载。</li><li><strong>工作流</strong>：路径固定的编排。</li><li><strong>插件</strong>：调外部 API。</li><li><strong>MCP</strong>：能力接口；技能可以指导何时用它。</li><li><strong>知识库</strong>：检索已有文档，不是操作手册。</li></ul><p>在扣子编程首页选 <strong>技能</strong> 页签，用自然语言生成 → 预览 → <strong>部署</strong> 后才能在扣子对话里用。企业旗舰版可以上企业技能商店。</p><h2 id="用-ai-编程生成全代码智能体" tabindex="-1">用 AI 编程生成全代码智能体 <a class="header-anchor" href="#用-ai-编程生成全代码智能体" aria-label="Permalink to &quot;用 AI 编程生成全代码智能体&quot;">​</a></h2><p>低代码画布不够定制时：</p><ol><li><a href="https://code.coze.cn/" target="_blank" rel="noreferrer">code.coze.cn</a> → <strong>智能体</strong> 选项卡。</li><li>写清功能、逻辑、约束；可选附件、问答/Agent 模式、技能、编程模型。</li><li>提交后等项目创建和单测。</li><li>右侧预览；报错丢回左侧对话，或用「一键修复」。</li><li>部署为 API 见 <a href="https://docs.coze.cn/guides_vibe_coding_agent" target="_blank" rel="noreferrer">部署智能体</a>。</li></ol><p>消耗：编程任务对话、内置集成、上线后的托管费。配额见 <a href="https://docs.coze.cn/guides_vibe_coding_limit" target="_blank" rel="noreferrer">配额与限制</a>。</p><p>团队版 / 企业版若看不到入口，先问超级管理员是否关了功能访问控制。</p><h2 id="发布到真正有人用的地方" tabindex="-1">发布到真正有人用的地方 <a class="header-anchor" href="#发布到真正有人用的地方" aria-label="Permalink to &quot;发布到真正有人用的地方&quot;">​</a></h2><p>发布概览把渠道分成三类（<a href="https://docs.coze.cn/guides_publish_overview" target="_blank" rel="noreferrer">guides_publish_overview</a>）：</p><ol><li><strong>官方默认</strong>：商店、飞书、微信、掘金、小程序、API、Chat SDK。</li><li><strong>团队自定义</strong>：硬件 / 应用市场入驻后，仅团队可用。智能体要发到「API 和团队自定义渠道」。</li><li><strong>公共渠道</strong>：企业旗舰版才能把渠道公开。</li></ol><p>流程：打包 → 扣子审核 → 渠道审核。</p><p>不要做的事：</p><ul><li>再找豆包渠道（2026-07-01 下线）。</li><li>指望复制商店里别人智能体的完整配置（商店是私有配置；要抄结构去<a href="https://www.coze.cn/template" target="_blank" rel="noreferrer">模板商店</a>）。</li><li>把工作流 / 图像流再上架到作品社区（已下架）。</li></ul><h2 id="用-coze-cli-让别的-agent-操作扣子" tabindex="-1">用 Coze CLI 让别的 Agent 操作扣子 <a class="header-anchor" href="#用-coze-cli-让别的-agent-操作扣子" aria-label="Permalink to &quot;用 Coze CLI 让别的 Agent 操作扣子&quot;">​</a></h2><p>官方包名 <strong><code>@coze/cli</code></strong>，命令名 <strong><code>coze</code></strong>。2026-08-19 在 npm 抽到 <code>0.3.10</code>。完整 flag 以 <code>coze --help</code> 和 <a href="https://www.npmjs.com/package/@coze/cli" target="_blank" rel="noreferrer">npm 页</a> 为准。</p><p>扣子对话里已经内置 CLI，一般用户直接下指令即可。在 Trae / Claude Code / 终端里：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @coze/cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --foreground-scripts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">coze</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> self</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 脚本里指定宿主，例如 Trae：</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># coze self skill install --target trae</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">coze</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oauth</span></span></code></pre></div><p>官方给 Agent 的第一句任务示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我用 Coze CLI 创建一个网页应用，介绍 Coze CLI 的功能及使用方式</span></span>
<span class="line"><span>创建完成后，请将预览链接发给我</span></span></code></pre></div><p>CLI 和扣子编程共用账号与工作空间。装 Skill 不是授权 CLI，是让宿主 Agent 知道何时调用它。</p><h2 id="必须私有化时" tabindex="-1">必须私有化时 <a class="header-anchor" href="#必须私有化时" aria-label="Permalink to &quot;必须私有化时&quot;">​</a></h2><p>扣子编程<strong>暂不支持</strong>私有化（<a href="https://docs.coze.cn/guides_FAQ" target="_blank" rel="noreferrer">FAQ</a>）。开源路径：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/coze-dev/coze-studio.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coze-studio</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># macOS / Linux</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span></span></code></pre></div><p>最低 2 核 4 GB，需要 Docker。浏览器打开 <code>http://localhost:8888/sign</code> 注册，再到 <code>/admin/#model-management</code> 配模型。公网部署前先读仓库 Quickstart 的安全警告。</p><p>Studio 是单机核：没有商业版的工作空间、企业组织、多人协作。评测观测的开源对应物是 <a href="https://github.com/coze-dev/coze-loop" target="_blank" rel="noreferrer">Coze Loop</a>。</p>`,52)])])}const C=e(o,[["render",n]]);export{u as __pageData,C as default};
